shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/src/parser.y
+++ b/src/parser.y
@@ -115,7 +115,7 @@
 %precedence "catch"


-%type <blk> Exp Term
+%type <blk> Exp Term IndexBase
 %type <blk> MkDict MkDictPair ExpD
 %type <blk> ElseBody
 %type <blk> String QQString
@@ -641,6 +641,15 @@
 }


+IndexBase:
+Term {
+  $$ = $1;
+} |
+Term '.' {
+  $$ = $1;
+}
+
+
 Term:
 '.' {
   $$ = gen_noop();
@@ -692,40 +701,34 @@
   $$ = gen_noop();
 } |
 /* FIXME: string literals */
-Term '[' Exp ']' '?' {
+IndexBase '[' Exp ']' '?' {
   $$ = gen_index_opt($1, $3);
 } |
-Term '[' Exp ']' %prec NONOPT {
+IndexBase '[' Exp ']' %prec NONOPT {
   $$ = gen_index($1, $3);
 } |
-Term '.' '[' Exp ']' '?' {
-  $$ = gen_index_opt($1, $4);
-} |
-Term '.' '[' Exp ']' %prec NONOPT {
-  $$ = gen_index($1, $4);
-} |
-Term '[' ']' '?' {
+IndexBase '[' ']' '?' {
   $$ = block_join($1, gen_op_simple(EACH_OPT));
 } |
-Term '[' ']' %prec NONOPT {
+IndexBase '[' ']' %prec NONOPT {
   $$ = block_join($1, gen_op_simple(EACH));
 } |
-Term '[' Exp ':' Exp ']' '?' {
+IndexBase '[' Exp ':' Exp ']' '?' {
   $$ = gen_slice_index($1, $3, $5, INDEX_OPT);
 } |
-Term '[' Exp ':' ']' '?' {
+IndexBase '[' Exp ':' ']' '?' {
   $$ = gen_slice_index($1, $3, gen_const(jv_null()), INDEX_OPT);
 } |
-Term '[' ':' Exp ']' '?' {
+IndexBase '[' ':' Exp ']' '?' {
   $$ = gen_slice_index($1, gen_const(jv_null()), $4, INDEX_OPT);
 } |
-Term '[' Exp ':' Exp ']' %prec NONOPT {
+IndexBase '[' Exp ':' Exp ']' %prec NONOPT {
   $$ = gen_slice_index($1, $3, $5, INDEX);
 } |
-Term '[' Exp ':' ']' %prec NONOPT {
+IndexBase '[' Exp ':' ']' %prec NONOPT {
   $$ = gen_slice_index($1, $3, gen_const(jv_null()), INDEX);
 } |
-Term '[' ':' Exp ']' %prec NONOPT {
+IndexBase '[' ':' Exp ']' %prec NONOPT {
   $$ = gen_slice_index($1, gen_const(jv_null()), $4, INDEX);
 } |
@@ -804,7 +807,7 @@
 } |
 '(' error ')' { $$ = gen_noop(); } |
 '[' error ']' { $$ = gen_noop(); } |
-Term '[' error ']' { $$ = $1; } |
+IndexBase '[' error ']' { $$ = $1; } |
 '{' error '}' { $$ = gen_noop(); }

 Args:
PATCH
make -j4 > /tmp/jq-chain-build.log 2>&1; result=$?; tail -50 /tmp/jq-chain-build.log; exit "$result"

cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('src/parser.y')
s = p.read_text()
s = s.replace('%type <blk> Exp Term
', '%type <blk> Exp Term IndexBase
')
s = s.replace('

Term:
', '

IndexBase:
Term {
  $$ = $1;
} |
Term '.' {
  $$ = $1;
}


Term:
')
dotted = "Term '.' '[' Exp ']' '?' {
  $$ = gen_index_opt($1, $4);
} |
Term '.' '[' Exp ']' %prec NONOPT {
  $$ = gen_index($1, $4);
} |
"
assert s.count(dotted) == 1
s = s.replace(dotted, '')
s = s.replace("Term '['", "IndexBase '['")
p.write_text(s)
PY
make -j4 > /tmp/jq-chain-build.log 2>&1; result=$?; tail -55 /tmp/jq-chain-build.log; exit "$result"

